'use strict';
const $=id=>document.getElementById(id),canvas=$('mindCanvas'),ctx=canvas.getContext('2d');
const state=createMindState(),rulePieces=[false,false,false],words=[null,null,null],ruleLabels=['薇洛处于潮湿','接触火焰言灵','火转蒸汽 · 不点燃'];
const meanings={sina:'你',o:'让',seli:'燃起火焰',telo:'变得潮湿',lete:'覆上寒霜'},statusNames={calm:'平静',wet:'潮湿',burning:'燃烧',cold:'寒冷'};
let bookOpen=false,ready=false,clock=0,last=0,pending=null,effect=null,ruleFlash=0,view={w:0,h:0,dpr:1},art={};
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const motes=Array.from({length:38},(_,i)=>({x:(i*137.31)%1,y:(i*73.71)%1,phase:i*2.17}));
function image(src){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(new Error('无法加载 '+src));im.src=src})}
function frames(im,cols,rows){const p=document.createElement('canvas');p.width=im.width;p.height=im.height;const c=p.getContext('2d',{willReadFrequently:true});c.drawImage(im,0,0);const data=c.getImageData(0,0,im.width,im.height).data,sw=im.width/cols,sh=im.height/rows,result=[];for(let row=0;row<rows;row++){result[row]=[];for(let col=0;col<cols;col++){let minX=sw,minY=sh,maxX=0,maxY=0;for(let y=3;y<sh-3;y++){for(let x=3;x<sw-3;x++){const at=(Math.floor(row*sh+y)*im.width+Math.floor(col*sw+x))*4+3;if(data[at]>60){minX=Math.min(minX,x);maxX=Math.max(maxX,x);minY=Math.min(minY,y);maxY=Math.max(maxY,y)}}}result[row][col]={sx:col*sw,sy:row*sh,sw,sh,anchorX:(minX+maxX)/2,anchorY:maxY,height:maxY-minY};}}return {image:im,frames:result};}
function setBook(open){bookOpen=open;$('bookShell').classList.toggle('opened',open);$('lexicon').classList.toggle('open',open);$('openBook').setAttribute('aria-expanded',String(open));$('openBook').tabIndex=open?-1:0;$('bookPages').inert=!open;$('closeBook').hidden=!open;$('bookHint').textContent=open?'点击词条，放入下方的言灵。':'翻开字典，取出你想说的话。';if(open)setTimeout(()=>{if(bookOpen)document.querySelector('[data-word="sina"]').focus({preventScroll:true})},500);else $('openBook').focus({preventScroll:true});}
$('openBook').onclick=()=>setBook(true);$('closeBook').onclick=()=>setBook(false);
function updateControls(){const busy=!!pending;
 document.querySelectorAll('[data-slot]').forEach(b=>{const i=Number(b.dataset.slot);b.classList.toggle('filled',rulePieces[i]);b.querySelector('span').textContent=rulePieces[i]?ruleLabels[i]:['放入状态','放入事件','放入结果'][i];b.disabled=state.ruleActive||busy});
 document.querySelectorAll('[data-fragment]').forEach(b=>{const selected=rulePieces[Number(b.dataset.fragment)];b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));b.disabled=state.ruleActive||busy});
 $('writeRule').disabled=busy||!rulePieces.every(Boolean);$('writeRule').innerHTML=state.ruleActive?'暂时移除规则 <span>−</span>':'写入推演 <span>↗</span>';$('ruleStatus').textContent=state.ruleActive?'已写入 · 等待触发':'尚未写入';$('ruleDot').classList.toggle('active',state.ruleActive);document.querySelector('.rule-panel').classList.toggle('active',state.ruleActive);
 document.querySelectorAll('[data-word-slot]').forEach(b=>{const value=words[Number(b.dataset.wordSlot)];b.querySelector('b').textContent=value||'…';b.classList.toggle('filled',!!value);b.disabled=busy});document.querySelectorAll('[data-word]').forEach(b=>{b.classList.toggle('selected',words.includes(b.dataset.word));b.setAttribute('aria-pressed',String(words.includes(b.dataset.word)));b.disabled=busy});
 $('cast').disabled=busy||!ready||!words.every(Boolean);$('cast').innerHTML=busy?'言灵行进中…':'施放言灵 <span>↗</span>';$('translation').textContent=words.every(Boolean)?'“你，'+meanings[words[2]]+'。”':words.filter(Boolean).length?'继续从字典取词，补全这句话。':'从右侧字典选择词语。';$('clearWords').disabled=busy;$('restoreSubject').disabled=busy;
 $('subjectState').textContent=statusNames[state.status];$('subjectState').className='status-pill '+state.status;
}
document.querySelectorAll('[data-fragment]').forEach(b=>b.onclick=()=>{if(pending||state.ruleActive)return;rulePieces[Number(b.dataset.fragment)]=true;updateControls()});
document.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>{if(pending||state.ruleActive)return;const i=Number(b.dataset.slot);rulePieces[i]=!rulePieces[i];updateControls()});
$('writeRule').onclick=()=>{if(pending||!rulePieces.every(Boolean))return;state.ruleActive=!state.ruleActive;ruleFlash=state.ruleActive?1.5:0;$('ruleNote').textContent=state.ruleActive?'规则已成为这层心象的一部分。':'潮湿 + 火焰 → 蒸汽，无法点燃。';$('subjectThought').textContent=state.ruleActive?'“假设已成立。现在，让它接受检验。”':'“暂时拿掉假设，结果会不同吗？”';updateControls()};
document.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{if(pending)return;const word=b.dataset.word;words[word==='sina'?0:word==='o'?1:2]=word;updateControls()});
document.querySelectorAll('[data-word-slot]').forEach(b=>b.onclick=()=>{if(pending)return;words[Number(b.dataset.wordSlot)]=null;updateControls()});
$('clearWords').onclick=()=>{if(pending)return;words.fill(null);updateControls()};
function cast(){if(pending||!ready||!words.every(Boolean))return;pending={word:words[2],elapsed:0};$('subjectThought').textContent='“'+words.join(' ')+'。”';updateControls()}
$('cast').onclick=cast;
function showResult(result){effect={type:result.effect,elapsed:0};$('trialNumber').textContent='推演 '+String(state.trials).padStart(2,'0');$('resultTitle').textContent=result.title;$('resultText').textContent=result.explanation;$('resultText').title=result.explanation;$('trace').hidden=false;$('traceInput').textContent=result.input;$('traceRule').textContent=result.rule;$('traceOutput').textContent=result.output;$('deduction').classList.add('has-trace');$('deduction').classList.toggle('hit',result.triggered);$('subjectThought').textContent=result.triggered?'“改变结果的，是规则。”':result.effect==='water'?'“前提准备好了，再试一次火焰。”':result.effect==='fire'?'“言灵生效了。规则会改变它吗？”':'“这一道言灵，没有碰到那条规则。”';if(result.triggered){ruleFlash=2.5;const panel=document.querySelector('.rule-panel');panel.classList.remove('triggered');void panel.offsetWidth;panel.classList.add('triggered');$('ruleStatus').textContent='刚刚触发 · 火焰已改写'}updateControls();if(result.triggered)$('ruleStatus').textContent='刚刚触发 · 火焰已改写'}
function restore(){state.status='calm';effect=null;ruleFlash=0;$('subjectThought').textContent='“回到原点，再验证一次。”';$('resultTitle').textContent='心象已还原';$('resultText').textContent='规则与言灵组合保留，可在相同条件下重新比较。';$('trace').hidden=true;$('deduction').classList.remove('has-trace','hit');updateControls()}
$('restoreSubject').onclick=restore;
$('resetMind').onclick=()=>{pending=null;Object.assign(state,createMindState());rulePieces.fill(false);words.fill(null);restore();$('trialNumber').textContent='尚未施放';$('resultTitle').textContent='现实尚未发生，念头可以重来。';$('resultText').textContent='先试一次火焰，再组装规则，比较水与火相遇后的结果。';$('ruleNote').textContent='潮湿 + 火焰 → 蒸汽，无法点燃。';setBook(false)};
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.repeat&&(!e.target.closest('button')||e.target.closest('[data-word]')||e.target.id==='cast')){e.preventDefault();cast()}if(e.key==='Escape'&&bookOpen)setBook(false)});
function resize(){view={w:innerWidth,h:innerHeight,dpr:Math.min(devicePixelRatio||1,2)};canvas.width=Math.round(view.w*view.dpr);canvas.height=Math.round(view.h*view.dpr)}window.addEventListener('resize',resize);resize();
function positions(){const mobile=view.w<=800;const mid=mobile?view.w/2:(287+view.w-388)/2;return {wilson:{x:mid-(mobile?57:86),y:mobile?265:view.h*.56},willow:{x:mid+(mobile?57:99),y:mobile?259:view.h*.535},height:mobile?95:Math.min(165,view.h*.21)}}
function glow(x,y,r,color){const g=ctx.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,color);g.addColorStop(1,'transparent');ctx.fillStyle=g;ctx.fillRect(x-r,y-r,r*2,r*2)}
function tag(text,x,y,color='#d8ddbd'){ctx.font='11px "Microsoft YaHei",sans-serif';ctx.textAlign='center';const w=ctx.measureText(text).width+18;ctx.fillStyle='#12231cdc';ctx.beginPath();ctx.roundRect(x-w/2,y-11,w,23,3);ctx.fill();ctx.fillStyle=color;ctx.fillText(text,x,y+4)}
function actor(sheet,f,pos,height,name,tint){const scale=height/sheet.frames[0][0].height;ctx.save();ctx.translate(pos.x,pos.y);ctx.fillStyle='#020c086b';ctx.beginPath();ctx.ellipse(0,0,29,10,0,0,Math.PI*2);ctx.fill();if(tint)glow(0,-height*.4,height*.8,tint);const bob=reduced?0:Math.sin(clock*1.65)*1.1;ctx.drawImage(sheet.image,f.sx,f.sy,f.sw,f.sh,-f.anchorX*scale,-f.anchorY*scale+bob,f.sw*scale,f.sh*scale);tag(name,0,22);ctx.restore()}
function drawStatus(p,height){const kind=state.status;ctx.save();ctx.translate(p.x,p.y);if(kind==='burning'){glow(0,-height*.45,110,'#f3973659');for(let i=0;i<22;i++){const age=(clock*1.1+i*.137)%1,x=Math.sin(i*2.5+clock*.9)*(24-age*10),y=-age*height*.85;ctx.globalAlpha=(1-age)*.7;ctx.fillStyle=i%2?'#ffc977':'#d77e38';ctx.beginPath();ctx.ellipse(x,y,7*(1-age)+2,14*(1-age)+2,-.2,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;}else if(kind==='wet'){ctx.strokeStyle='#95d3d29c';ctx.lineWidth=1.5;for(let i=0;i<15;i++){const y=((clock*.7+i*.103)%1)*height-height,x=Math.sin(i*3.8)*32;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-2,y+7);ctx.stroke()}ctx.strokeStyle='#a9dedb9c';ctx.beginPath();ctx.ellipse(0,1,38+Math.sin(clock*3)*3,12,0,0,Math.PI*2);ctx.stroke();}else if(kind==='cold'){glow(0,-height*.45,85,'#a3d9e635');ctx.strokeStyle='#c1e5e4b8';ctx.lineWidth=1;for(let i=0;i<8;i++){const x=Math.sin(i*3.1)*37,y=-15-i*height/10;ctx.save();ctx.translate(x+Math.sin(clock+i)*2,y);for(let j=0;j<3;j++){ctx.rotate(Math.PI/3);ctx.beginPath();ctx.moveTo(-4,0);ctx.lineTo(4,0);ctx.stroke()}ctx.restore()}}ctx.restore()}
function drawEffect(p,height){if(!effect)return;const t=effect.elapsed;ctx.save();ctx.translate(p.x,p.y);if(effect.type==='steam'&&t<4){for(let i=0;i<16;i++){const age=(t*.45+i*.071)%1;ctx.globalAlpha=Math.max(0,1-t/4)*(1-age)*.6;ctx.fillStyle='#d9e6d8';ctx.beginPath();ctx.ellipse(Math.sin(i*2.8+t*.5)*(20+age*40),-age*(height+45),10+age*24,9+age*30,-.3,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;if(t<2.8)tag('蒸汽 · 未点燃',0,-height-30,'#f0deb0')}else if(t<1.1){ctx.globalAlpha=1-t/1.1;ctx.strokeStyle=effect.type==='water'?'#a3e0df':effect.type==='frost'?'#d3ebf5':'#edc18a';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,-height*.4,20+t*65,30+t*45,0,0,Math.PI*2);ctx.stroke()}ctx.restore()}
function draw(){ctx.setTransform(view.dpr,0,0,view.dpr,0,0);const scale=Math.max(view.w/art.ground.width,view.h/art.ground.height);ctx.drawImage(art.ground,(view.w-art.ground.width*scale)/2,(view.h-art.ground.height*scale)/2,art.ground.width*scale,art.ground.height*scale);
 const p=positions(),h=p.height;glow((p.wilson.x+p.willow.x)/2,p.willow.y-45,250,'#adc39515');
 // Quiet drifting motes and offset ellipses make the remembered camp slightly unreal.
 ctx.strokeStyle='#c4d4a225';ctx.lineWidth=1;ctx.setLineDash([2,12]);ctx.beginPath();ctx.ellipse((p.wilson.x+p.willow.x)/2,p.willow.y+12,145,42,-.07,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);
 for(const m of motes){const x=m.x*view.w+Math.sin(clock*.17+m.phase)*12,y=m.y*view.h+Math.sin(clock*.2+m.phase)*9;ctx.globalAlpha=.15+Math.sin(clock*.5+m.phase)*.12;ctx.fillStyle='#d6dfb5';ctx.fillRect(x,y,2,2)}ctx.globalAlpha=1;
 if(state.ruleActive){ctx.strokeStyle=ruleFlash>0?'#dfce8c99':'#becfa139';ctx.lineWidth=1;ctx.setLineDash([4,7]);ctx.beginPath();ctx.moveTo(p.wilson.x,p.wilson.y-h-9);ctx.bezierCurveTo(p.wilson.x-25,p.wilson.y-h-85,p.willow.x+10,p.willow.y-h-85,p.willow.x,p.willow.y-h-9);ctx.stroke();ctx.setLineDash([]);const cx=(p.wilson.x+p.willow.x)/2,cy=Math.min(p.wilson.y,p.willow.y)-h-55;ctx.save();ctx.translate(cx,cy);ctx.rotate(Math.PI/4);ctx.strokeRect(-6,-6,12,12);ctx.restore();}
 const willowFrame=effect?.type==='steam'&&effect.elapsed<3?1:({calm:0,burning:1,wet:2,cold:3}[state.status]);actor(art.willow,art.willow.frames[0][willowFrame],p.willow,h,'薇洛 · 心象',state.status==='wet'?'#89d1d320':state.status==='burning'?'#eea24b22':null);actor(art.wilson,art.wilson.frames[1][0],p.wilson,h,'威尔逊 · 推演者',null);drawStatus(p.willow,h);drawEffect(p.willow,h);
 if(pending){const t=Math.min(pending.elapsed/1.1,1),x=p.wilson.x+(p.willow.x-p.wilson.x)*t,y=p.wilson.y-h*.6+(p.willow.y-p.wilson.y)*t-Math.sin(t*Math.PI)*45;glow(x,y,40,'#d8d9a658');tag(pending.word,x,y,'#f5e7ae');tag('sina o '+pending.word,p.wilson.x,p.wilson.y-h-24,'#e7dfb3');}
}
function frame(stamp){const dt=Math.min((stamp-last)/1000,.05);last=stamp;if(!document.hidden){if(!reduced)clock+=dt;if(ruleFlash>0)ruleFlash-=dt;if(effect)effect.elapsed+=dt;if(pending){pending.elapsed+=dt;if(pending.elapsed>=1.1){const word=pending.word;pending=null;showResult(resolveUtterance(state,word))}}if(ready)draw()}requestAnimationFrame(frame)}
Promise.all([image('assets/mind-ground.png'),image('assets/wilson-sprite.png'),image('assets/willow-mind-sprite.png')]).then(([ground,wilson,willow])=>{art={ground,wilson:frames(wilson,4,4),willow:frames(willow,4,1)};ready=true;$('loadingMind').hidden=true;updateControls()}).catch(error=>{$('loadingMind').querySelector('p').textContent=error.message+'，请刷新重试。'});
updateControls();requestAnimationFrame(frame);
